// `incl`: an arg to include in the error even if not used
fn missing_required_error(&self, matcher: &ArgMatcher, incl: Vec<Id>) -> ClapResult<()> {
    debug!("Validator::missing_required_error; incl={:?}", incl);
    debug!(
        "Validator::missing_required_error: reqs={:?}",
        self.required
    );

    let usg = Usage::new(self.cmd).required(&self.required);

    let mut req_args = usg
        .get_required_usage_from(&incl, Some(matcher), true)
        .into_iter()
        .collect::<Vec<_>>();

    // `get_required_usage_from` skips args that belong to an already-satisfied
    // `ArgGroup`, but we still want to call out an explicitly `incl`uded arg
    // (e.g. one that is unconditionally `requires`d) even if it is a group member.
    for id in &incl {
        if !matcher.check_explicit(id, ArgPredicate::IsPresent) {
            if let Some(arg) = self.cmd.find(id) {
                let arg = arg.to_string();
                if !req_args.contains(&arg) {
